  if g[r][c]!=3 or (r,c) in seen: continue
  q=deque([(r,c)]); seen.add((r,c)); comp=[]
  while q:
   x,y=q.popleft(); comp.append((x,y))
   for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
    z=(x+dx,y+dy)
    if 0<=z[0]<R and 0<=z[1]<C and z not in seen and g[z[0]][z[1]]==3:
     seen.add(z);q.append(z)
  comps.append(comp)
